/// Gets the Grapheme Break property for a code point using two-stage trie lookup
pub fn getGraphemeBreakProperty(cp: Codepoint) GraphemeBreak {
    if (cp > 0x10FFFF) return .Other;
    const block = @as(usize, cp >> 8);
    if (block >= gb_stage1.len) return .Other;
    const offset = @as(usize, cp & 0xFF);
    const stage2_idx = gb_stage1[block] + offset;
    if (stage2_idx >= gb_stage2.len) return .Other;
    return @enumFromInt(gb_stage2[stage2_idx]);
}
